"""Bundle the pure renderer into a self-contained, editable HTML studio."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
mods={name:'function(module,exports,require){\n'+(R/'dist'/f'{name}.js').read_text()+'\n}' for name in ['types','templates','metrics','render-stamp','examples']}
bundle='const factories={'+','.join(json.dumps('./'+k)+':'+v for k,v in mods.items())+'};const cache={};function require(id){if(cache[id])return cache[id].exports;const m={exports:{}};cache[id]=m;factories[id](m,m.exports,require);return m.exports;}const Kit=require("./render-stamp");const templates=require("./templates").TEMPLATES;const samples=require("./examples").EXAMPLES;window.CaptroKit={...Kit,templates,samples};'
css=r'''
:root{color-scheme:light;--paper:#f4f1ea;--ink:#28362c;--mute:#677064;--line:#d2d3c7;--green:#284d3c}*{box-sizing:border-box}body{background:var(--paper);color:var(--ink);margin:0;font:14px/1.45 Inter,Arial,sans-serif}button,input,select{font:inherit}button{cursor:pointer;color:inherit}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--green);outline-offset:4px}button{border:1px solid var(--line);background:transparent;padding:10px 15px;border-radius:4px}button[aria-pressed=true]{background:var(--green);border-color:var(--green);color:#fff8e8}.frame{max-width:1510px;margin:auto;padding:0 48px}header{padding-top:32px!important}.top{display:flex;justify-content:space-between;align-items:center;padding-bottom:19px;border-bottom:1px solid var(--line)}.wordmark{font-size:21px;letter-spacing:-1px;font-weight:600}.edition{font-size:11px;letter-spacing:2.1px;text-transform:uppercase;color:var(--mute)}.intro{display:flex;justify-content:space-between;align-items:end;margin:32px 0 25px;gap:25px}.intro h1{font:400 49px/.95 'EB Garamond',Georgia,serif;letter-spacing:-1.6px;margin:0 0 13px}.intro p{color:var(--mute);margin:0;max-width:630px}.spec{font-size:12px;white-space:nowrap;color:var(--mute)}.controls{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:20px 0;border-top:1px solid var(--line)}nav{display:flex;gap:6px;flex-wrap:wrap}nav button{padding:8px 13px;font-size:12px}.density{display:flex;align-items:center;gap:9px;color:var(--mute);font-size:12px}select{border:1px solid var(--line);background:#faf8f1;border-radius:4px;padding:8px;color:var(--ink)}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:35px 36px;padding:14px 0 35px}.cell{min-width:0}.art{display:flex;align-items:center;justify-content:center;min-height:195px}.stamp-button{display:block;border:0;background:none;width:100%;padding:0;border-radius:0}.stamp-button svg{display:block;width:100%;height:auto}.stamp-button:hover{transform:translateY(-2px)}.caption{margin:14px 6px 0;display:flex;justify-content:space-between;color:var(--mute);font-size:11px;gap:8px}.caption strong{font-weight:500}.caption span{white-space:nowrap}.empty{grid-column:1/-1}footer{border-top:1px solid var(--line);padding:22px 0 32px!important;font-size:12px;color:var(--mute)}dialog{width:1020px;max-width:calc(100vw - 26px);max-height:92vh;padding:0;border:1px solid #b5bbae;border-radius:8px;color:var(--ink);background:#faf8f2}dialog::backdrop{background:#13241988}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:23px 28px;border-bottom:1px solid var(--line)}.dialog-head h2{font:400 32px/1.1 'EB Garamond',Georgia,serif;margin:0}.close{border:0;font-size:25px;padding:4px 10px;line-height:1}.editor-grid{display:grid;grid-template-columns:1.15fr 1fr}.preview-panel{padding:28px;border-right:1px solid var(--line)}.stage{display:flex;align-items:center;justify-content:center;min-height:235px;padding:24px 12px;background:#ece9e1;border-radius:5px;overflow:hidden}.stage[data-surface=dark]{background:#343c37}.stage[data-surface=white]{background:#fff}.stage svg{display:block;width:100%;height:auto}#live{width:100%;max-width:100%}.stage-controls{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:17px}.surface-controls{display:flex;gap:6px}.surface-controls button{padding:5px 9px;font-size:11px}.size-row{display:flex;align-items:center;gap:10px;margin:19px 0;color:var(--mute);font-size:12px}.size-row input{width:100%;accent-color:var(--green)}.below{font-size:12px;color:var(--mute);line-height:1.65}.edit-panel{padding:25px;max-height:65vh;overflow-y:auto}.fields{display:grid;grid-template-columns:1fr;gap:13px}.fields label{display:flex;flex-direction:column;gap:6px;font-size:11px;letter-spacing:.25px;color:var(--mute)}.fields input{width:100%;border:1px solid var(--line);background:#fffefa;padding:10px 11px;border-radius:3px;color:var(--ink);font-size:14px}.editor-footer{display:flex;justify-content:space-between;align-items:center;gap:15px;border-top:1px solid var(--line);padding:18px 26px;flex-wrap:wrap}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions button{font-size:12px;padding:10px 12px}.primary{background:var(--green);border-color:var(--green);color:#fff9e9}.status{font-size:11px;color:#7d4932;min-height:17px;margin-top:12px}details{margin-top:19px;font-size:12px;color:var(--mute)}details button{font-size:11px;padding:7px 10px;margin:9px 3px 0 0}.save-note{font-size:11px;color:var(--mute)}@media(max-width:1100px){.art{min-height:145px}.frame{padding:0 28px}.gallery{gap:27px 23px}.intro h1{font-size:42px}}@media(max-width:800px){.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.spec{display:none}.editor-grid{grid-template-columns:1fr}.preview-panel{border-right:0;border-bottom:1px solid var(--line);padding:20px}.stage{min-height:195px}.edit-panel{max-height:40vh}.editor-footer{padding:15px 20px}.dialog-head{padding:18px 20px}}@media(max-width:540px){.frame{padding:0 20px}.intro{margin-top:26px}.intro h1{font-size:38px}.intro p{font-size:13px}.gallery{grid-template-columns:1fr;gap:26px}.art{min-height:0}.caption{margin-top:10px}.density{width:100%;justify-content:space-between}.edition{letter-spacing:1.3px;font-size:10px}nav{gap:5px}nav button{padding:7px 10px}.controls{padding:15px 0}.stage-controls{flex-wrap:wrap}.dialog-head h2{font-size:26px}}@media(prefers-reduced-motion:reduce){.stamp-button:hover{transform:none}}
'''
body=r'''
<header class="frame"><div class="top"><div class="wordmark">captro</div><div class="edition">Stamp library / Edition 02</div></div><div class="intro"><div><h1>A little more character.</h1><p>Fifteen editable designs. Five stamp types. Choose a stamp to change its text, preview it at feed size, or export an individual asset.</p></div><div class="spec">Vector artwork · Full & compact layouts</div></div><div class="controls"><nav aria-label="Stamp types"><button data-filter="all" aria-pressed="true">All 15</button><button data-filter="moment" aria-pressed="false">Moment</button><button data-filter="club" aria-pressed="false">Club</button><button data-filter="event" aria-pressed="false">Event</button><button data-filter="meetup" aria-pressed="false">Meetup</button><button data-filter="deal" aria-pressed="false">Deal</button></nav><div class="density"><label for="gallery-density">Layout</label><select id="gallery-density"><option value="full">Full / details</option><option value="compact">Compact / feed</option></select><button id="feed-size" aria-pressed="false">Show at 232px</button></div></div></header>
<main class="frame"><div id="gallery" class="gallery" aria-label="Editable stamp designs"></div><footer>All names, offers, dates and memberships here are sample content. Editing this file does not change Captro or publish anything. No accounts, tracking or network requests.</footer></main>
<dialog id="editor"><div class="dialog-head"><h2 id="editor-title">Edit stamp</h2><button class="close" id="close" aria-label="Close editor">×</button></div><div class="editor-grid"><section class="preview-panel" aria-label="Stamp preview"><div class="stage" id="stage" data-surface="paper"><div id="live"></div></div><div class="stage-controls"><select id="edit-density" aria-label="Preview layout"><option value="full">Full / details</option><option value="compact">Compact / feed</option></select><div class="surface-controls" aria-label="Preview background"><button data-surface="paper" aria-pressed="true">Paper</button><button data-surface="white" aria-pressed="false">White</button><button data-surface="dark" aria-pressed="false">Dark</button></div></div><div class="size-row"><label for="size">Size</label><input id="size" type="range" min="200" max="450" value="420" step="1"><output id="size-value" for="size">420px</output></div><p class="below">Use the compact version around 232px wide in the feed. Full layouts belong on larger detail views. Typography uses installed fonts with system fallbacks; the ZIP also includes outlined references with fixed lettering.</p><div id="status" class="status" role="status"></div></section><section class="edit-panel" aria-label="Editable fields"><div class="fields" id="fields"></div><details><summary>More exports</summary><button id="frame-export">Blank SVG frame</button><button id="data-export">App data JSON</button><button id="reset">Reset example</button></details></section></div><div class="editor-footer"><div class="actions"><button class="primary" id="svg-export">Export editable SVG</button><button id="png-export">Export PNG · 4×</button><button id="apply">Apply to preview</button></div><span class="save-note">Preview edits last until this page is refreshed.</span></div></dialog>
'''
js=r'''
let filter='all',density='full',small=false,current=null,original=null;
const $=id=>document.getElementById(id);const editor=$('editor');
const names={'moment-paper':'Paper keepsake','moment-postal':'Postal impression','moment-voice':'Voice note','club-oval':'Society seal','club-member':'Member pass','club-tag':'Studio tag','event-ticket':'Admission ticket','event-screening':'Cinema pass','event-postal':'Postal invitation','meetup-note':'Field note','meetup-fold':'Folded invitation','meetup-route':'Route marker','deal-coupon':'Classic coupon','deal-cashback':'Reward receipt','deal-drop':'Local drop'};
function gallery(){const parent=$('gallery');parent.replaceChildren();samples.filter(s=>filter==='all'||s.type===filter).forEach(s=>{const article=document.createElement('article');article.className='cell';article.dataset.variant=s.variant;const art=document.createElement('div');art.className='art';const button=document.createElement('button');button.className='stamp-button';button.type='button';button.setAttribute('aria-label','Edit '+names[s.variant]);button.innerHTML=Kit.renderStamp(s,{density});if(small){button.style.width='232px';button.style.maxWidth='100%'}button.onclick=()=>open(s);art.append(button);const caption=document.createElement('div');caption.className='caption';const a=document.createElement('strong');a.textContent=names[s.variant];const b=document.createElement('span');b.textContent='Edit stamp ↗';caption.append(a,b);article.append(art,caption);parent.append(article);});}
function draw(){const mode=$('edit-density').value;const width=Number($('size').value);$('live').style.width=width+'px';$('size-value').textContent=width+'px';try{$('live').innerHTML=Kit.renderStamp(current,{density:mode});const nodes=[...$('live').querySelectorAll('text')];$('status').textContent=nodes.some(x=>x.textContent.includes('…')||['SEE DETAILS','VIEW OFFER','INFO'].includes(x.textContent))?'Some text is shortened at this size. Full content remains in the exported app data.':''}catch(e){$('status').textContent=e.message}}
function fields(){const used=new Set([...templates[current.variant].full.fields,...templates[current.variant].compact.fields].map(f=>f.key));$('fields').replaceChildren();const labels={title:'Main text',meta:'Place / supporting line',footer:'Full details / price / terms',compactText:'Compact summary for the feed',sideTop:'Date month',sideMain:current.variant==='moment-voice'?'Audio duration':current.type==='event'?'Date day':'Short action',sideBottom:'Action detail'};for(const key of ['title','meta','footer','compactText','sideTop','sideMain','sideBottom']){if(!used.has(key))continue;const label=document.createElement('label');label.textContent=labels[key];const input=document.createElement('input');input.type='text';input.maxLength=160;input.value=current[key]||'';input.dataset.field=key;input.oninput=()=>{current={...current,[key]:input.value};draw()};label.append(input);$('fields').append(label)}}
function open(s){original=JSON.parse(JSON.stringify(s));current=JSON.parse(JSON.stringify(s));$('editor-title').textContent=names[s.variant];$('edit-density').value=density;$('size').value=small?232:420;fields();draw();editor.showModal()}
function save(bytes,type,name){const blob=new Blob([bytes],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportSVG(frameOnly=false){try{save(Kit.renderStamp(current,{density:$('edit-density').value,frameOnly}),'image/svg+xml;charset=utf-8',current.variant+'-'+$('edit-density').value+(frameOnly?'-frame':'')+'.svg')}catch(e){$('status').textContent=e.message}}
async function exportPNG(){const mode=$('edit-density').value;const btn=$('png-export');btn.disabled=true;try{await document.fonts.ready;const svg=Kit.renderStamp(current,{density:mode,width:2560});const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('The browser could not render the SVG. Export the editable SVG instead.'));image.src=url});const canvas=document.createElement('canvas');canvas.width=2560;canvas.height=mode==='compact'?896:1152;canvas.getContext('2d').drawImage(image,0,0);URL.revokeObjectURL(url);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('PNG export failed in this browser.');save(blob,'image/png',current.variant+'-'+mode+'@4x.png');$('status').textContent='Exported a transparent 4× PNG.'}catch(e){$('status').textContent=e.message}finally{btn.disabled=false}}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));gallery()});$('gallery-density').onchange=e=>{density=e.target.value;gallery()};$('feed-size').onclick=()=>{small=!small;$('feed-size').textContent=small?'Show larger artwork':'Show at 232px';$('feed-size').setAttribute('aria-pressed',String(small));gallery()};document.querySelectorAll('button[data-surface]').forEach(b=>b.onclick=()=>{$('stage').dataset.surface=b.dataset.surface;document.querySelectorAll('button[data-surface]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});$('close').onclick=()=>editor.close();$('size').oninput=draw;$('edit-density').onchange=draw;$('svg-export').onclick=()=>exportSVG();$('frame-export').onclick=()=>exportSVG(true);$('png-export').onclick=exportPNG;$('data-export').onclick=()=>save(JSON.stringify(current,null,2),'application/json',current.variant+'.json');$('reset').onclick=()=>{current=JSON.parse(JSON.stringify(original));fields();draw()};$('apply').onclick=()=>{const i=samples.findIndex(s=>s.variant===current.variant);samples[i]=JSON.parse(JSON.stringify(current));gallery();editor.close()};gallery();
'''
html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Captro — Stamp Studio V2</title><style>'+css+'</style></head><body>'+body+'<script>'+bundle+'\n'+js+'</script></body></html>'
(R/'studio.html').write_text(html,encoding='utf-8')
print('Built offline stamp studio with SVG, transparent PNG and app-data exports.')
